// BoolOrNumber is a value DCS gives as a boolean or a number; exactly one of
// Bool and Number is set.
type BoolOrNumber struct {
	Bool   *bool
	Number *float64
}

// UnmarshalJSON accepts a boolean or a number and rejects any other JSON.
func (v *BoolOrNumber) UnmarshalJSON(b []byte) error {
	*v = BoolOrNumber{}
	t := bytes.TrimSpace(b)
	if len(t) > 0 {
		switch c := t[0]; {
		case c == 't' || c == 'f':
			var x bool
			if err := json.Unmarshal(t, &x); err == nil {
				v.Bool = &x
				return nil
			}
		case c == '-' || (c >= '0' && c <= '9'):
			var x float64
			if err := json.Unmarshal(t, &x); err == nil {
				v.Number = &x
				return nil
			}
		}
	}
	return fmt.Errorf("dcsref: want a boolean or a number, got %s", t)
}

// MarshalJSON writes the member that is set (null if none is).
func (v BoolOrNumber) MarshalJSON() ([]byte, error) {
	switch {
	case v.Bool != nil:
		return json.Marshal(*v.Bool)
	case v.Number != nil:
		return json.Marshal(*v.Number)
	}
	return []byte("null"), nil
}

